10	import org.springframework.web.bind.annotation.RequestMapping;
11	import org.springframework.web.bind.annotation.RestController;
12	
13	/**
14	 * Per-spec data setup for the harness (DESIGN.md §9). Profile-guarded so it exists ONLY under the
15	 * harness launch (bin/start sets spring.profiles.active=harness) — never in a real deploy. This is
16	 * APP CODE and EVOLVES with the schema (NOT pinned); a change that breaks a prior spec's seed is a
17	 * seed-path regression. Tests call these to ARRANGE data; they ASSERT only through the UI.
18	 *
19	 * <p>{@link #seed} is a plain sequence of one {@code seed*} method per entity. Teaching a new entity
20	 * to the harness is therefore additive: add its {@code seed*} method, call it from {@link #seed},
21	 * and add its {@code TRUNCATE} to {@link #reset} — no existing entity's code is touched.
22	 */
23	@Profile("harness")
24	@RestController
25	@RequestMapping("/__test__")
26	public class TestSupportController {
27	
28	    private final Audit audit;
29	    private final JdbcTemplate jdbc;
30	
31	    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
32	        this.audit = audit;
33	        this.jdbc = jdbc;
34	    }
35	
36	    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
37	    @PostMapping("/reset")
38	    public void reset() {
39	        audit.clear();
40	        // Referential integrity is dropped for the duration so the tables can be truncated (and
41	        // their identity counters restarted) regardless of FK order (e.g. projects -> clients).
42	        jdbc.execute("SET REFERENTIAL_INTEGRITY FALSE");
43	        for (String table : List.of("notes", "project_tags", "tags", "tasks", "payments",
44	                "line_items", "invoices", "contacts", "projects", "clients")) {
45	            jdbc.execute("TRUNCATE TABLE " + table + " RESTART IDENTITY");
46	        }
47	        jdbc.execute("SET REFERENTIAL_INTEGRITY TRUE");
48	    }
49	
50	    /** Insert the fixture a spec needs; each entity is seeded by its own {@code seed*} method. */
51	    @PostMapping("/seed")
52	    public void seed(@RequestBody Map<String, Object> fixture) {
53	        seedClients(fixture);
54	        seedProjects(fixture);
55	        seedContacts(fixture);
56	        seedInvoices(fixture);
57	        seedPayments(fixture);
58	        seedTasks(fixture);
59	        seedTags(fixture);
60	        seedNotes(fixture);
61	        seedProjectTags(fixture);
62	    }
63	
64	    private void seedClients(Map<String, Object> fixture) {
65	        for (Map<String, Object> c : rows(fixture, "clients")) {
66	            jdbc.update("INSERT INTO clients (id, name, email) VALUES (?, ?, ?)",
67	                    id(c, "id"), c.get("name"), c.get("email"));
68	        }
69	    }
70	
71	    private void seedProjects(Map<String, Object> fixture) {
72	        for (Map<String, Object> p : rows(fixture, "projects")) {
73	            // status defaults to ACTIVE so a fixture that omits it gets an active project.
74	            jdbc.update(
75	                    "INSERT INTO projects (id, name, client_id, status) VALUES (?, ?, ?, ?)",
76	                    id(p, "id"), p.get("name"), id(p, "clientId"),
77	                    p.get("status") == null ? "ACTIVE" : p.get("status").toString());
78	        }
79	    }
80	
81	    private void seedContacts(Map<String, Object> fixture) {
82	        for (Map<String, Object> ct : rows(fixture, "contacts")) {
83	            jdbc.update(
84	                    "INSERT INTO contacts (id, client_id, name, email, role) VALUES (?, ?, ?, ?, ?)",
85	                    id(ct, "id"), id(ct, "clientId"), ct.get("name"), ct.get("email"),
86	                    ct.get("role"));
87	        }
88	    }
89	
90	    private void seedInvoices(Map<String, Object> fixture) {
91	        for (Map<String, Object> in : rows(fixture, "invoices")) {
92	            // Insert only the columns the fixture supplies, so the table's own defaults apply when a
93	            // fixture omits them (a plain null would trip the NOT NULL columns). status defaults to
94	            // DRAFT and amount defaults to 0 — an invoice's amount is derived from its line items,
95	            // so fixtures list lineItems rather than a single typed amount.
96	            new Insert("invoices")
97	                    .set("id", id(in, "id"))
98	                    .set("project_id", id(in, "projectId"))
99	                    .set("status", in.get("status") == null ? "DRAFT" : in.get("status").toString())
100	                    .setIfPresent("amount", asDouble(in.get("amount")))
101	                    .setIfPresent("issued_date", asText(in.get("issuedDate")))
102	                    .setIfPresent("due_date", asText(in.get("dueDate")))
103	                    .run();
104	            seedLineItems(in);
105	        }
106	    }
107	
108	    private void seedLineItems(Map<String, Object> invoice) {
109	        long invoiceId = id(invoice, "id");
110	        for (Map<String, Object> li : rows(invoice, "lineItems")) {
111	            jdbc.update(
112	                    "INSERT INTO line_items (id, invoice_id, description, qty, unit_price)"
113	                            + " VALUES (?, ?, ?, ?, ?)",
114	                    id(li, "id"), invoiceId, li.get("description"),
115	                    ((Number) li.get("qty")).intValue(),
116	                    ((Number) li.get("unitPrice")).doubleValue());
117	        }
118	    }
119	
120	    private void seedPayments(Map<String, Object> fixture) {
121	        List<Map<String, Object>> payments = rows(fixture, "payments");
122	        for (Map<String, Object> p : payments) {
123	            jdbc.update(
124	                    "INSERT INTO payments (id, invoice_id, amount, paid_date) VALUES (?, ?, ?, ?)",
125	                    id(p, "id"), id(p, "invoiceId"), asDouble(p.get("amount")),
126	                    asText(p.get("date")));
127	        }
128	        if (!payments.isEmpty()) {
129	            // Seeding explicit ids does not advance H2's identity counter, so bump it past the
130	            // seeded rows or the app's next generated payment id would collide with a fixture id.
131	            Long next = jdbc.queryForObject("SELECT MAX(id) + 1 FROM payments", Long.class);
132	            jdbc.execute("ALTER TABLE payments ALTER COLUMN id RESTART WITH " + next);
133	        }
134	    }
135	
136	    private void seedTasks(Map<String, Object> fixture) {
137	        for (Map<String, Object> t : rows(fixture, "tasks")) {
138	            jdbc.update("INSERT INTO tasks (id, project_id, title, done) VALUES (?, ?, ?, ?)",
139	                    id(t, "id"), id(t, "projectId"), t.get("title"),
140	                    Boolean.TRUE.equals(t.get("done")));
141	        }
142	    }
143	
144	    private void seedTags(Map<String, Object> fixture) {
145	        for (Map<String, Object> tg : rows(fixture, "tags")) {
146	            jdbc.update("INSERT INTO tags (id, name) VALUES (?, ?)", id(tg, "id"), tg.get("name"));
147	        }
148	    }
149	
150	    private void seedNotes(Map<String, Object> fixture) {
151	        List<Map<String, Object>> notes = rows(fixture, "notes");
152	        for (Map<String, Object> n : notes) {
153	            jdbc.update(
154	                    "INSERT INTO notes (id, target_type, target_id, text, created_at)"
155	                            + " VALUES (?, ?, ?, ?, ?)",
156	                    id(n, "id"), n.get("targetType"), id(n, "targetId"), n.get("text"),
157	                    n.get("at").toString());
158	        }
159	        if (!notes.isEmpty()) {
160	            // Seeding explicit ids does not advance H2's identity counter, so bump it past the
161	            // seeded rows or the app's next generated note id would collide with a fixture id.
162	            Long next = jdbc.queryForObject("SELECT MAX(id) + 1 FROM notes", Long.class);
163	            jdbc.execute("ALTER TABLE notes ALTER COLUMN id RESTART WITH " + next);
164	        }
165	    }
166	
167	    private void seedProjectTags(Map<String, Object> fixture) {
168	        for (Map<String, Object> pt : rows(fixture, "projectTags")) {
169	            jdbc.update("INSERT INTO project_tags (project_id, tag_id) VALUES (?, ?)",
170	                    id(pt, "projectId"), id(pt, "tagId"));
171	        }
172	    }
173	
174	    /** The list of fixture rows under {@code key}, or an empty list when the fixture omits it. */
175	    @SuppressWarnings("unchecked")
176	    private static List<Map<String, Object>> rows(Map<String, Object> fixture, String key) {
177	        return (List<Map<String, Object>>) fixture.getOrDefault(key, List.of());
178	    }
179	
180	    /** A fixture id column: JSON numbers arrive as {@link Number}, the tables use {@code BIGINT}. */
181	    private static long id(Map<String, Object> row, String key) {
182	        return ((Number) row.get(key)).longValue();
183	    }
184	
185	    private static Double asDouble(Object value) {
186	        return value == null ? null : ((Number) value).doubleValue();
187	    }
188	
189	    private static String asText(Object value) {
190	        return value == null ? null : value.toString();
191	    }
192	
193	    /**
194	     * Builds an {@code INSERT} whose column set is decided per row, so a fixture can omit a column
195	     * and let the table's own default apply (a bare null would trip a NOT NULL column). Required
196	     * columns are added with {@link #set}; optional ones with {@link #setIfPresent}.
197	     */
198	    private final class Insert {
199	        private final String table;
200	        private final StringBuilder cols = new StringBuilder();
201	        private final StringBuilder marks = new StringBuilder();
202	        private final List<Object> args = new ArrayList<>();
203	
204	        Insert(String table) {
205	            this.table = table;
206	        }
207	
208	        Insert set(String column, Object value) {
209	            if (cols.length() > 0) {
210	                cols.append(", ");
211	                marks.append(", ");
212	            }
213	            cols.append(column);
214	            marks.append("?");
215	            args.add(value);
216	            return this;
217	        }
218	
219	        Insert setIfPresent(String column, Object value) {
220	            return value == null ? this : set(column, value);
221	        }
222	
223	        void run() {
224	            jdbc.update("INSERT INTO " + table + " (" + cols + ") VALUES (" + marks + ")",
225	                    args.toArray());
226	        }
227	    }
228	}
